begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
-- Only Auth scaffolding is inserted. Every business object/grant below is
-- created through its real authenticated public command, not seeded authority.
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)select pg_temp.id(n),'synthetic-milestone-'||n||'@example.test',now(),'{"role":"owner","clinical_signer":true}'::jsonb from generate_series(1,4)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,4)n;
create temporary table evidence(key text primary key,value jsonb);grant all on evidence to authenticated;
create function pg_temp.put(k text,v jsonb)returns jsonb language sql as $$insert into evidence values(k,v)on conflict(key)do update set value=excluded.value returning value$$;
create function pg_temp.v(k text)returns jsonb language sql stable as $$select value from evidence where key=k$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('role','owner','clinical_signer',true))::text,true)$$;
create function pg_temp.zone()returns text language sql stable as $$select case when 12-extract(hour from now()at time zone'UTC')::integer=0 then'Etc/UTC' else'Etc/GMT'||case when 12-extract(hour from now()at time zone'UTC')::integer>0 then'-'else'+'end||abs(12-extract(hour from now()at time zone'UTC')::integer)::text end$$;
create function pg_temp.practice(n integer)returns uuid language sql stable as $$select(pg_temp.v('owner'||n)->>'practice_id')::uuid$$;
create function pg_temp.location(n integer)returns uuid language sql stable as $$select case when n=3 then(pg_temp.v('second')->>'location_id')::uuid else(pg_temp.v('owner'||n)->>'location_id')::uuid end$$;
create function pg_temp.patient(n integer)returns uuid language sql stable as $$select(pg_temp.v('patient'||n)->>'patient_id')::uuid$$;
create function pg_temp.appointment(n integer)returns uuid language sql stable as $$select(pg_temp.v('booking'||n)->>'appointment_id')::uuid$$;
create function pg_temp.onboard(n integer)returns jsonb language plpgsql as $$declare draft jsonb;begin
 draft:=public.doctor_save_onboarding_draft(p_key=>pg_temp.id(100+n),p_expected_version=>0,p_display_name=>'Synthetic doctor '||n,p_practice_name=>'Synthetic practice '||n,p_location_name=>'Synthetic clinic '||n,p_timezone=>pg_temp.zone());
 return public.doctor_complete_onboarding(p_key=>pg_temp.id(100+n),p_draft_version=>(draft->>'version')::integer);end$$;
create function pg_temp.board(n integer)returns jsonb language sql as $$select public.doctor_appointment_board(p_practice=>pg_temp.practice(n),p_location=>pg_temp.location(n),p_day=>(now()at time zone pg_temp.zone())::date)$$;
create function pg_temp.transition(n integer,state text,version integer,key integer)returns jsonb language sql as $$select public.doctor_transition_appointment(p_practice=>pg_temp.practice(n),p_location=>pg_temp.location(n),p_appointment=>pg_temp.appointment(n),p_expected_version=>version,p_state=>state,p_reason=>'',p_key=>pg_temp.id(key))$$;
create function pg_temp.book(n integer)returns jsonb language plpgsql as $$declare configuration jsonb;schedule jsonb;slot jsonb;begin
 configuration:=public.doctor_schedule(pg_temp.practice(n),pg_temp.location(n));
 schedule:=public.doctor_write_schedule(p_practice=>pg_temp.practice(n),p_location=>pg_temp.location(n),p_expected_version=>0,p_location_version=>(configuration->>'location_version')::integer,p_input=>jsonb_build_object('slot_minutes',20,'weekly',(select jsonb_agg(jsonb_build_object('weekday',d,'start',540,'end',1020))from generate_series(0,6)d),'exceptions','[]'::jsonb),p_key=>pg_temp.id(200+n));
 select item into slot from jsonb_array_elements(public.doctor_availability(pg_temp.practice(n),pg_temp.location(n),(now()at time zone pg_temp.zone())::date)->'slots')item where(item->>'available')::boolean and(item->>'starts_at')::timestamptz>now()+interval'1 minute' order by item->>'starts_at'limit 1;
 return public.doctor_book_appointment(p_practice=>pg_temp.practice(n),p_location=>pg_temp.location(n),p_patient=>pg_temp.patient(n),p_day=>(now()at time zone pg_temp.zone())::date,p_minute=>(slot->>'minute')::integer,p_schedule_version=>(schedule->>'version')::integer,p_location_version=>(schedule->>'location_version')::integer,p_key=>pg_temp.id(300+n));end$$;
set local role authenticated;select pg_temp.claim(1);
select pg_temp.put('owner1',pg_temp.onboard(1));
select is(public.doctor_complete_onboarding(pg_temp.id(101),1)->>'practice_id',pg_temp.v('owner1')->>'practice_id','C01 onboarding receipt creates one owner practice');
select pg_temp.put('second',public.doctor_write_location(p_practice=>pg_temp.practice(1),p_name=>'Synthetic second clinic',p_timezone=>'Europe/London',p_phone=>'',p_address=>'',p_key=>pg_temp.id(111)));
select is(jsonb_array_length(public.doctor_contexts()),2,'C01 doctor alone owns two independently zoned clinics');
select is(public.doctor_practice_setup()->'profile'->>'professional_verification','unverified','C04 editable metadata never verifies professional authority');
select pg_temp.put('patient1',public.doctor_write_patient(p_practice=>pg_temp.practice(1),p_location=>pg_temp.location(1),p_input=>'{"name":"Synthetic M1 A patient","phone":"","email":"","date_of_birth":null}',p_key=>pg_temp.id(121)));
select is(public.doctor_write_patient(p_practice=>pg_temp.practice(1),p_location=>pg_temp.location(1),p_input=>'{"name":"Synthetic M1 A patient","phone":"","email":"","date_of_birth":null}',p_key=>pg_temp.id(121))->>'patient_id',pg_temp.v('patient1')->>'patient_id','C01 lost patient reply retries without another identity');
select pg_temp.put('booking1',pg_temp.book(1));
select is(pg_temp.transition(1,'checked_in',1,401)->>'state','checked_in','C01 owner checks into own queue');
select is(pg_temp.transition(1,'checked_in',1,401)->>'version','2','C01 uncertain check-in replay has one effective transition');
select is(pg_temp.board(1)->>'queue_total','1','C01 one queue entry survives duplicate intent');
select is(public.doctor_patient_profile(pg_temp.practice(1),pg_temp.location(1),pg_temp.patient(1))->'patient'->>'id',pg_temp.v('patient1')->>'patient_id','C01 full patient profile follows created relationship');
select pg_temp.claim(2);select pg_temp.put('owner2',pg_temp.onboard(2));
select pg_temp.put('patient2',public.doctor_write_patient(p_practice=>pg_temp.practice(2),p_location=>pg_temp.location(2),p_input=>'{"name":"Synthetic M1 B patient","phone":"","email":"","date_of_birth":null}',p_key=>pg_temp.id(122)));
select pg_temp.put('booking2',pg_temp.book(2));
select throws_ok($$select pg_temp.board(1)$$,'42501','DOCTOR_ACCESS_DENIED','C02 doctor B cannot borrow doctor A authority');
select pg_temp.put('invite2',public.doctor_invite_secretary(p_practice=>pg_temp.practice(2),p_email=>'synthetic-milestone-3@example.test',p_grants=>jsonb_build_array(jsonb_build_object('location_id',pg_temp.location(2),'capabilities',array['patients.read','appointments.read'])),p_token_hash=>encode(sha256(decode(repeat('b',64),'hex')),'hex'),p_key=>pg_temp.id(502)));
select pg_temp.claim(1);
select pg_temp.put('invite1',public.doctor_invite_secretary(p_practice=>pg_temp.practice(1),p_email=>'synthetic-milestone-3@example.test',p_grants=>jsonb_build_array(jsonb_build_object('location_id',pg_temp.location(1),'capabilities',array['patients.read','appointments.read','queue.manage'])),p_token_hash=>encode(sha256(decode(repeat('a',64),'hex')),'hex'),p_key=>pg_temp.id(501)));
select throws_ok($$select public.doctor_invite_secretary(p_practice=>pg_temp.practice(1),p_email=>'synthetic-milestone-4@example.test',p_grants=>jsonb_build_array(jsonb_build_object('location_id',pg_temp.location(1),'capabilities',array['clinical.sign'])),p_token_hash=>repeat('c',64),p_key=>pg_temp.id(503))$$,'22023',null,'C04 administrative catalogue cannot delegate clinical signing');
select pg_temp.claim(3);
select is(public.doctor_session_context()->>'practice_id',null,'C02 forged owner metadata does not create a practice');
select public.doctor_accept_secretary_invitation((pg_temp.v('invite1')->>'invitation_id')::uuid,repeat('a',64),pg_temp.id(511));
select public.doctor_accept_secretary_invitation((pg_temp.v('invite2')->>'invitation_id')::uuid,repeat('b',64),pg_temp.id(512));
select is(jsonb_array_length(public.doctor_contexts()),2,'C02 secretary accepts two independent real command invitations');
select ok(not exists(select 1 from jsonb_array_elements(public.doctor_contexts())item where item->>'portal'<>'secretary' or item->>'location_id'=pg_temp.location(3)::text),'C02 owner metadata and A1 grants cannot manufacture A2 access');
select is(pg_temp.transition(1,'in_progress',2,402)->>'state','in_progress','C02 A1 queue grant authorizes one attributed command');
select is(public.doctor_patient_profile(pg_temp.practice(2),pg_temp.location(2),pg_temp.patient(2))->'patient'->>'id',pg_temp.v('patient2')->>'patient_id','C02 B1 read works independently');
select throws_ok($$select pg_temp.transition(2,'checked_in',1,403)$$,'42501','DOCTOR_ACCESS_DENIED','C02 B1 read cannot manage its queue');
select throws_ok($$select public.doctor_patient_profile(pg_temp.practice(1),pg_temp.location(3),pg_temp.patient(1))$$,'42501','DOCTOR_ACCESS_DENIED','C02 A1 grant cannot expose A2 profile context');
select throws_ok($$select public.doctor_patient_profile(pg_temp.practice(1),pg_temp.location(1),pg_temp.patient(2))$$,'42501','DOCTOR_ACCESS_DENIED','C02 substituting a foreign patient cannot cross relationships');
select throws_ok($$select public.doctor_write_patient(p_practice=>pg_temp.practice(1),p_location=>pg_temp.location(1),p_input=>'{"name":"Synthetic denied","phone":"","email":"","date_of_birth":null}',p_key=>pg_temp.id(123))$$,'42501','DOCTOR_ACCESS_DENIED','C02 queue management cannot create patients');
select pg_temp.claim(4);select throws_ok($$select pg_temp.board(1)$$,'42501','DOCTOR_ACCESS_DENIED','C02 outsider metadata cannot read another doctor queue');
select pg_temp.claim(1);
select pg_temp.put('member1',(public.doctor_team(pg_temp.practice(1))->'members')->0);
select public.doctor_set_membership_status(pg_temp.practice(1),(pg_temp.v('member1')->>'id')::uuid,(pg_temp.v('member1')->>'version')::integer,'revoked',pg_temp.id(521));
select pg_temp.claim(3);
select throws_ok($$select pg_temp.board(1)$$,'42501','DOCTOR_ACCESS_DENIED','C02 same SID loses revoked A read');
select throws_ok($$select pg_temp.transition(1,'completed',3,404)$$,'42501','DOCTOR_ACCESS_DENIED','C02 same SID loses revoked A write');
select throws_ok($$select public.doctor_accept_secretary_invitation((pg_temp.v('invite1')->>'invitation_id')::uuid,repeat('a',64),pg_temp.id(511))$$,'42501',null,'C02 acceptance replay cannot restore revoked membership');
select is(pg_temp.board(2)->>'total','1','C02 independent B still works after A revocation');
select pg_temp.claim(1);
select is(public.doctor_appointment_history(pg_temp.practice(1),pg_temp.location(1),pg_temp.appointment(1))->>'total','3','C02 history retains booking check-in and staff start after revocation');
select is((select item->>'actor_user_id'from jsonb_array_elements(public.doctor_appointment_history(pg_temp.practice(1),pg_temp.location(1),pg_temp.appointment(1))->'events')item where item->>'type'='appointment.in_progress'),pg_temp.id(3)::text,'C02 retained history attributes the actual staff actor');
select is(public.doctor_administrative_audit(pg_temp.practice(1),null,'appointment.in_progress')->'items'->0->>'actor_user_id',pg_temp.id(3)::text,'C02 safe audit retains the same actor');
reset role;delete from auth.sessions where id=pg_temp.id(13);set local role authenticated;select pg_temp.claim(3);
select throws_ok($$select pg_temp.board(2)$$,'42501','DOCTOR_AUTH_REQUIRED','C02 removed provider SID invalidates remaining B grants');
select pg_temp.claim(2);select is(pg_temp.board(2)->>'total','1','C02 secretary SID removal does not revoke doctor B');
select *from finish();rollback;
